INSERT INTO public.vehicles (id, slug, category, brand, model, year, starting_price, emi_from, images, three_sixty_images, thumbnail_url, fuel_types, transmissions, mileage, features, colors, rating, review_count, is_new, is_best_seller, is_ev, seating_capacity, boot_space_l, engine_cc, power_bhp, torque_nm, safety_rating, description, pros, cons, ground_clearance) VALUES ('tata-sierra-2026', 'tata-sierra', 'car', 'Tata', 'Sierra', 2026, 1500000, 28500, '{"https://images.91wheels.com/assets/c_images/gallery/tata/sierra/tata-sierra-0-1768365444.png","https://images.91wheels.com/assets/c_images/gallery/tata/sierra/tata-sierra-7-1768365448.png","https://images.91wheels.com/assets/c_images/gallery/tata/sierra/tata-sierra-3-1768365446.png","https://images.91wheels.com/assets/c_images/gallery/tata/sierra/tata-sierra-5-1768365447.png","https://images.91wheels.com/assets/c_images/gallery/tata/sierra/tata-sierra-1-1768365445.png","https://images.91wheels.com/assets/c_images/gallery/tata/sierra/tata-sierra-6-1768365447.png","https://images.91wheels.com/assets/c_images/gallery/tata/sierra/tata-sierra-4-1768365446.png","https://images.91wheels.com/assets/c_images/gallery/tata/sierra/tata-sierra-2-1768365445.png"}', '{}', 'https://images.91wheels.com/assets/c_images/gallery/tata/sierra/tata-sierra-0-1768365444.png', '{"Petrol","Electric"}', '{"Manual","Automatic"}', '18.0 kmpl / 500 km range', '{"Iconic Curved Glasshouse Rear Design","Dual 10.25-inch Touchscreen & Digital Cluster","Level 2 ADAS Autonomous Safety Suite","Panoramic Skyroof","Ventilated Front Seats","Flush Door Handles","JBL 9-Speaker Premium Sound System","Wireless Apple CarPlay & Android Auto"}', '{"Calypso Blue","Pristine White","Daytona Grey","Organic Green"}', 4.8, 450, TRUE, FALSE, TRUE, 5, 450, 1498, 170, 280, 5, 'The iconic Tata Sierra returns as a next-generation SUV featuring legendary curved glasshouse rear windows, futuristic twin digital screens, Level 2 ADAS, panoramic sunroof, and ultra-refined turbo petrol & EV powertrains.', '{"Nostalgic iconic glasshouse styling combined with modern futuristic cues","Spacious lounge-like cabin with premium JBL audio and ADAS","Refined 1.5L TGDi Turbo Petrol (170 PS) engine"}', '{"3-row seating option not available"}', 205) ON CONFLICT (id) DO UPDATE SET starting_price = EXCLUDED.starting_price, images = EXCLUDED.images, colors = EXCLUDED.colors;
