INSERT INTO public.vehicles (id, slug, category, brand, model, year, starting_price, emi_from, images, three_sixty_images, thumbnail_url, fuel_types, transmissions, mileage, features, colors, rating, review_count, is_new, is_best_seller, is_ev, seating_capacity, boot_space_l, engine_cc, power_bhp, torque_nm, safety_rating, description, pros, cons, ground_clearance) VALUES ('tata-nexon-2026', 'tata-nexon', 'car', 'Tata', 'Nexon', 2026, 799000, 15000, '{"https://images.91wheels.com/assets/c_images/gallery/tata/nexon/tata-nexon-0-1784198581.png","https://images.91wheels.com/assets/c_images/gallery/tata/nexon/tata-nexon-6-1766220426.png","https://images.91wheels.com/assets/c_images/gallery/tata/nexon/tata-nexon-7-1766220427.png","https://images.91wheels.com/assets/c_images/gallery/tata/nexon/tata-nexon-2-1766220423.png","https://images.91wheels.com/assets/c_images/gallery/tata/nexon/tata-nexon-5-1766220426.png","https://images.91wheels.com/assets/c_images/gallery/tata/nexon/tata-nexon-3-1766220424.png","https://images.91wheels.com/assets/c_images/gallery/tata/nexon/tata-nexon-1-1766220423.png","https://images.91wheels.com/assets/c_images/gallery/tata/nexon/tata-nexon-4-1766220425.png"}', '{}', 'https://images.91wheels.com/assets/c_images/gallery/tata/nexon/tata-nexon-0-1784198581.png', '{"Petrol","Diesel"}', '{"Manual","Automatic","DCT"}', '17.0 - 23.2 kmpl', '{"10.25-inch Touchscreen Infotainment by Harman","10.25-inch Full Digital Instrument Cluster with Map Navigation","360-Degree Surround View HD Camera","Ventilated Leatherette Front Seats","Voice-Assisted Electric Sunroof","JBL 9-Speaker Audio System with Subwoofer","6 Airbags Standard Across All Trims","Sequential LED DRLs & Animated Taillamps","Wireless Apple CarPlay & Android Auto","Air Purifier with AQI Display"}', '{"Fearless Purple","Creative Ocean","Flame Red","Daytona Grey","Pristine White","Pure Grey"}', 4.6, 3100, TRUE, TRUE, FALSE, 5, 382, 1199, 118, 170, 5, 'The Tata Nexon facelift features aggressive coupe-SUV styling, 5-star GNCAP safety rating, 10.25-inch Harman touchscreen infotainment, 10.25-inch digital cockpit with full map display, 360-degree HD camera, ventilated seats, and multiple engine & transmission options including 7-speed DCA.', '{"Unbeatable 5-star GNCAP safety rating with 6 standard airbags","High 208mm ground clearance handles deep potholes with ease","Futuristic interior with dual 10.25-inch screens and JBL sound","Wide powertrain matrix: Petrol, Diesel, DCA, and AMT options"}', '{"Touch-based climate controls require getting used to","Rear headroom slightly reduced due to sleek roofline"}', 208) ON CONFLICT (id) DO UPDATE SET starting_price = EXCLUDED.starting_price, images = EXCLUDED.images, colors = EXCLUDED.colors;
