FALSE, TRUE, FALSE, 7, 384, 1493, 100, 260, 4, 'The Mahindra Bolero Neo is a tough 7-seater body-on-frame compact SUV featuring mHawk100 diesel engine, Multi-Terrain Technology (MTT) mechanical locking differential, 7-inch touchscreen, and rugged steel body construction.', '{"True body-on-frame tough SUV construction tackles semi-urban roads with ease","Multi-Terrain Tech (MTT) locking differential helps get out of muddy ruts","High seating capacity for up to 7 passengers"}', '{"No automatic gearbox option available","Side-facing 3rd-row seats lack 3-point seatbelts"}', 180) ON CONFLICT (id) DO UPDATE SET starting_price = EXCLUDED.starting_price, images = EXCLUDED.images, colors = EXCLUDED.colors;
