 120, 172, 4, 'The Hyundai Venue compact SUV combines dark chrome front grille styling, Level 1 ADAS safety features, 4-way powered driver seat, 8-inch touchscreen with Bluelink connected car tech, and multiple powertrain options including 1.5L Diesel.', '{"Rich features matrix including powered driver seat and ADAS","Smooth 1.0L Turbo Petrol DCT and refined 1.5L Diesel engines","Compact city-friendly dimensions with light controls"}', '{"Rear seat cabin width is snug for 3 adults","Bumpy ride over sharp potholes at low speeds"}', 195) ON CONFLICT (id) DO UPDATE SET starting_price = EXCLUDED.starting_price, images = EXCLUDED.images, colors = EXCLUDED.colors;
